import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation for approximating set membership.
    Uses a simple bit array and multiple hash functions to manage space
    efficiently while allowing for a configurable rate of false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array (m) and number of hash functions (k)
        self.size = self._optimal_bit_array_size()
        self.hash_count = self._optimal_number_of_hashes()
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return -int(self.expected_items * math.log(self.false_positive_rate) / (math.log(2) ** 2))

    def _optimal_number_of_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the given item."""
        return [int(hashlib.md5((item + str(i)).encode('utf-8')).hexdigest(), 16) % self.size for i in range(self.hash_count)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check for membership of an item in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

